perl - <<'EOF'
use strict; use warnings;
use IPC::Open3;
use Symbol 'gensym';

my $REF='/workspace/dataset/test16_executable';
my $RUST='/output/test16';

my @chars=('a','A','1','+','-','.','_',' ','',':');
my @inputs;
for my $n (1,2,3) {
  my @idx=(0) x $n;
  while (1) {
    push @inputs, join('', map {$chars[$_]} @idx).'://x.y/p';
    my $i=$n-1;
    while ($i>=0) { if (++$idx[$i] < @chars) { last } $idx[$i]=0; $i--; }
    last if $i<0;
  }
}
push @inputs, 'a?b://c','x#y://z','?://h','#://h','a?://h',
  '://h','://','a://b://c','http://a://b','://://x',
  'http:/x','http:x','//x','/x','http:\\x';

sub run {
  my ($bin,$arg)=@_;
  my $err=gensym;
  my $pid=open3(undef, my $out, $err, $bin, $arg);
  local $/;
  my $stdout=<$out>;
  waitpid($pid,0);
  my $rc=$?>>8;
  return ($rc, defined $stdout ? $stdout : '');
}

sub esc {
  my $s=shift;
  $s =~ s/([\\'])/\\$1/g;
  $s =~ s/([^\x20-\x7e])/sprintf("\\x%02x",ord($1))/ge;
  return "'$s'";
}

my $mism=0;
for my $s (@inputs) {
  my ($rc1,$o1)=run($REF,$s);
  my ($rc2,$o2)=run($RUST,$s);
  if ($rc1!=$rc2 || $o1 ne $o2) {
    $mism++;
    print "MISMATCH input: ",esc($s),"\n";
    print "  ref : rc=$rc1 out=",esc($o1),"\n";
    print "  rust: rc=$rc2 out=",esc($o2),"\n";
  }
}
print "total tested: ",scalar(@inputs)," mismatches: $mism\n";
EOF

perl - <<'EOF'
use strict; use warnings;
use IPC::Open3;
use Symbol 'gensym';

my $REF='/workspace/dataset/test16_executable';
my $RUST='/output/test16';

my @chars=('a','A','1','+','-','.','_',' ','',':');
srand(20260810);
my @inputs;
my %seen;
while (@inputs < 4000) {
  my $n = 4 + int(rand(2));  # 4 or 5 chars
  my $s = join('', map { $chars[int(rand(@chars))] } 1..$n).'://x.y/p';
  next if $seen{$s}++;
  push @inputs, $s;
}
# a few extra structural variants
push @inputs, 'a://b://c://d', '://x://y', 'a?#://h', '?#://h', 'a ://h', ' ://h', 'a+.-://h', '1+2.3-4://h';

sub run {
  my ($bin,$arg)=@_;
  my $err=gensym;
  my $pid=open3(undef, my $out, $err, $bin, $arg);
  local $/;
  my $stdout=<$out>;
  waitpid($pid,0);
  return ($?>>8, defined $stdout ? $stdout : '');
}
sub esc { my $s=shift; $s =~ s/([\\'])/\\$1/g; $s =~ s/([^\x20-\x7e])/sprintf("\\x%02x",ord($1))/ge; "'$s'" }

my $mism=0;
for my $s (@inputs) {
  my ($rc1,$o1)=run($REF,$s);
  my ($rc2,$o2)=run($RUST,$s);
  if ($rc1!=$rc2 || $o1 ne $o2) {
    $mism++;
    print "MISMATCH input: ",esc($s),"\n";
    print "  ref : rc=$rc1 out=",esc($o1),"\n";
    print "  rust: rc=$rc2 out=",esc($o2),"\n";
  }
}
print "total tested: ",scalar(@inputs)," mismatches: $mism\n";
EOF
